        Integer version=jdbc.sql("SELECT current_version+1 FROM proposals WHERE id=? FOR UPDATE").param(proposalId).query(Integer.class).single();UUID versionId=UUID.randomUUID();Instant now=clock.instant();
        jdbc.sql("UPDATE proposal_versions SET status='SUPERSEDED',superseded_at=? WHERE proposal_id=? AND document_type='FINAL_TREATMENT_QUOTE' AND status IN ('RELEASED','VIEWED','REVISION_REQUESTED','EXPIRED','CLINICALLY_APPROVED','FINANCE_APPROVED')").params(timestamp(now),proposalId).update();
        String includedServices=items.stream().map(EstRow::description).collect(java.util.stream.Collectors.joining("; "));
        jdbc.sql("INSERT INTO proposal_versions(id,proposal_id,version_number,status,document_type,scope_change_reason,language,clinical_review_id,currency,included_services,excluded_services,payment_terms,refund_terms,disclaimers,coordinator_notes,valid_until,requires_finance_approval,provider_net_egp,commercial_policy_id,commercial_policy_version,margin_rate,margin_amount_egp,patient_total_min_egp,patient_total_expected_egp,patient_total_max_egp,clinical_approved_by,clinical_approved_at,created_by,created_at) SELECT ?,?,?,?,?,?, ?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,approved_by,approved_at,?,? FROM clinical_review_versions WHERE id=?").params(versionId,proposalId,version,"CLINICALLY_APPROVED","FINAL_TREATMENT_QUOTE",request.scopeChangeReason(),"en",request.clinicalReviewId(),displayCurrency,includedServices,request.excludedServices(),request.paymentTerms(),request.refundTerms(),request.disclaimers(),request.coordinatorNotes(),timestamp(request.validUntil()),requiresFinance,providerNet,policyId,policyVersion,marginRate,marginAmount,pMin,pExp,pMax,actor.subject(),timestamp(now),request.clinicalReviewId()).update();
