    @Transactional public IdResponse emergencyOverride(UUID caseId,EmergencyOverrideRequest request){
        var actor=actors.require(ActorRole.DOCTOR);authorizeWrite(caseId,actor);requireActiveAssignment(caseId,actor,ActorRole.DOCTOR);requireOneOfStates(caseId,Set.of("ARRIVAL_CONFIRMED","TREATMENT_IN_PROGRESS"));
        if(request.reason()==null||request.reason().isBlank())throw new ApiException(400,"OVERRIDE_REASON_REQUIRED","A reason is required for an emergency treatment override");
        UUID patientId=jdbc.sql("SELECT patient_id FROM medical_cases WHERE id=?").param(caseId).query(UUID.class).single();UUID id=UUID.randomUUID();Instant now=clock.instant();
        jdbc.sql("INSERT INTO consent_records(id,patient_id,case_id,consent_type,policy_version,language,exact_text,purpose,scope,channel,captured_by,effective_from,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)").params(id,patientId,caseId,"EMERGENCY_TREATMENT_OVERRIDE","v1","en",request.reason(),"Emergency treatment override","Emergency care before formal consent","EMERGENCY",actor.subject(),timestamp(now),timestamp(now)).update();
        jdbc.sql("INSERT INTO case_tasks(id,case_id,task_type,title,description,owner_subject,owner_role,visibility_scope,priority,status,blocking,due_at,created_by,created_at,updated_at,version) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0)").params(UUID.randomUUID(),caseId,"EMERGENCY_OVERRIDE_REVIEW","enc:"+crypto.encrypt("Post-event review of emergency treatment override"),encryptNullable(request.reason()),actor.subject(),"DOCTOR","INTERNAL","HIGH","OPEN",false,timestamp(now.plus(Duration.ofDays(2))),actor.subject(),timestamp(now),timestamp(now)).update();
        audit("EMERGENCY_TREATMENT_OVERRIDE",actor,caseId,"ConsentRecord",id.toString(),"OVERRIDE","SUCCESS",request.reason());return new IdResponse(id,"EMERGENCY_OVERRIDE");
    }
    private boolean hasTreatmentAuthorization(UUID caseId){Integer c=jdbc.sql("SELECT count(*) FROM consent_records WHERE case_id=? AND consent_type IN ('PROCEDURE_SPECIFIC','EMERGENCY_TREATMENT_OVERRIDE') AND revoked_at IS NULL").param(caseId).query(Integer.class).single();return c!=null&&c>0;}
    private void requireFinalQuoteAcceptedIfAny(UUID caseId){UUID latestFinal=jdbc.sql("SELECT pv.id FROM proposal_versions pv JOIN proposals p ON p.id=pv.proposal_id WHERE p.case_id=? AND pv.document_type='FINAL_TREATMENT_QUOTE' AND pv.status<>'SUPERSEDED' ORDER BY pv.version_number DESC LIMIT 1").param(caseId).query(UUID.class).optional().orElse(null);if(latestFinal==null)return;Integer accepted=jdbc.sql("SELECT count(*) FROM proposal_decisions WHERE proposal_version_id=? AND decision='ACCEPTED'").param(latestFinal).query(Integer.class).single();if(accepted==null||accepted==0)throw new ApiException(409,"FINAL_QUOTE_NOT_ACCEPTED","The final treatment quote must be accepted before treatment");}
    @Transactional public IdResponse followUp(UUID caseId,FollowUpRequest request){var actor=actors.require(ActorRole.DOCTOR);authorizeWrite(caseId,actor);requireActiveAssignment(caseId,actor,ActorRole.DOCTOR);requireState(caseId,"DISCHARGED");UUID actorPractitioner=practitionerId(actor.subject());if(request.practitionerId()!=null&&!request.practitionerId().equals(actorPractitioner))throw new ApiException(403,"PRACTITIONER_IDENTITY_MISMATCH","A doctor may only create follow-up under their own verified practitioner profile");if(request.treatmentEpisodeId()!=null){Integer episode=jdbc.sql("SELECT count(*) FROM treatment_episodes WHERE id=? AND case_id=?").params(request.treatmentEpisodeId(),caseId).query(Integer.class).single();if(episode==null||episode==0)throw new ApiException(409,"INVALID_TREATMENT_EPISODE","The treatment episode does not belong to this case");}UUID id=UUID.randomUUID();Instant now=clock.instant();jdbc.sql("INSERT INTO follow_up_plans(id,case_id,treatment_episode_id,practitioner_id,due_at,mode,required_tests,instructions,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)").params(id,caseId,request.treatmentEpisodeId(),actorPractitioner,timestamp(request.dueAt()),request.mode(),request.requiredTests(),request.instructions(),"PLANNED",timestamp(now),timestamp(now)).update();transitionWithoutVersion(caseId,"FOLLOW_UP","Follow-up plan created",actor);audit("FOLLOW_UP_CREATED",actor,caseId,"FollowUpPlan",id.toString(),"CREATE","SUCCESS",null);return new IdResponse(id,"PLANNED");}

    private CaseView caseView(UUID caseId){return jdbc.sql("SELECT * FROM medical_cases WHERE id=?").param(caseId).query((rs,n)->mapCase(rs)).optional().orElseThrow(()->new ApiException(404,"CASE_NOT_FOUND","Case was not found"));}
    private CaseView mapCase(ResultSet rs)throws SQLException{UUID id=rs.getObject("id",UUID.class);String coordinator=assignment(id,"COORDINATOR");String doctor=assignment(id,"DOCTOR");return new CaseView(id,rs.getString("case_number"),rs.getString("status"),rs.getString("full_name"),rs.getString("country"),rs.getString("preferred_language"),rs.getString("care_category"),instant(rs,"created_at"),instant(rs,"updated_at"),rs.getLong("version"),coordinator,doctor,staffName(coordinator),doctorName(id),rs.getBoolean("travel_package_requested"));}
    private String doctorName(UUID caseId){String subject=jdbc.sql("SELECT assignee_subject FROM case_assignments WHERE case_id=? AND assignee_role='DOCTOR' AND status IN ('PENDING','ACTIVE') ORDER BY assigned_at DESC LIMIT 1").param(caseId).query(String.class).optional().orElse(null);if(subject==null)return null;return jdbc.sql("SELECT display_name FROM practitioner_profiles WHERE external_subject=?").param(subject).query(String.class).optional().orElse(null);}
    private String assignment(UUID caseId,String role){return jdbc.sql("SELECT assignee_subject FROM case_assignments WHERE case_id=? AND assignee_role=? AND status='ACTIVE' ORDER BY assigned_at DESC LIMIT 1").params(caseId,role).query(String.class).optional().orElse(null);}
    private String staffName(String subject){if(subject==null)return null;return jdbc.sql("SELECT display_name_encrypted FROM staff_members WHERE external_subject=?").param(subject).query(String.class).optional().map(crypto::decrypt).orElse(null);}
    private TaskView mapTask(ResultSet rs)throws SQLException{Instant due=instantNullable(rs,"due_at");return new TaskView(rs.getObject("id",UUID.class),rs.getObject("case_id",UUID.class),rs.getString("task_type"),decryptStored(rs.getString("title")),decryptStored(rs.getString("description")),rs.getString("owner_subject"),rs.getString("owner_role"),rs.getString("visibility_scope"),rs.getString("priority"),rs.getString("status"),rs.getBoolean("blocking"),due!=null&&due.isBefore(clock.instant())&&!Set.of("COMPLETED","CANCELLED").contains(rs.getString("status")),due,rs.getLong("version"));}
    private MessageView mapMessage(ResultSet rs,ActorContext.Actor actor)throws SQLException{String subject=rs.getString("sender_subject");String role=rs.getString("sender_role");return new MessageView(rs.getObject("id",UUID.class),rs.getString("thread_type"),role,senderName(subject,role),subject.equals(actor.subject())?"OUTBOUND":"INBOUND",decryptStored(rs.getString("body")),rs.getString("language"),rs.getBoolean("internal_only"),subject.equals(actor.subject())||rs.getBoolean("actor_read"),instant(rs,"created_at"));}
    private String senderName(String subject,String role){if("DOCTOR".equals(role))return jdbc.sql("SELECT display_name FROM practitioner_profiles WHERE external_subject=?").param(subject).query(String.class).optional().orElse("Doctor");if(Set.of("COORDINATOR","COORDINATOR_LEAD","OPERATIONS","FINANCE").contains(role))return staffName(subject);return "Patient";}
    private String decryptStored(String value){if(value==null)return null;if(!value.startsWith("enc:"))return value;return crypto.decrypt(value.substring(4));}
    private String encryptNullable(String value){return value==null||value.isBlank()?null:"enc:"+crypto.encrypt(value.trim());}
    private void requireAcceptedStaffAssignment(UUID caseId,ActorContext.Actor actor){if(actor.has(ActorRole.PATIENT)||actor.has(ActorRole.PATIENT_REPRESENTATIVE)||actor.has(ActorRole.SYSTEM_ADMIN)||actor.has(ActorRole.COORDINATOR_LEAD)||actor.has(ActorRole.AUDITOR))return;for(ActorRole role:Set.of(ActorRole.COORDINATOR,ActorRole.DOCTOR,ActorRole.OPERATIONS,ActorRole.FINANCE))if(actor.has(role)){requireActiveAssignment(caseId,actor,role);return;}}
    private void validateTask(TaskRequest request){if(!Set.of("INFORMATION_REQUEST","DOCUMENT_REVIEW","CLINICAL_REVIEW","PROPOSAL","TRAVEL","TREATMENT","FOLLOW_UP","OTHER").contains(request.taskType()))throw new ApiException(400,"INVALID_TASK_TYPE","Select a supported task type");if(!Set.of("LOW","NORMAL","HIGH","URGENT").contains(request.priority()))throw new ApiException(400,"INVALID_TASK_PRIORITY","Select a supported task priority");}
    private void validateTaskOwner(UUID caseId,String subject,String role){if(!Set.of("PATIENT","COORDINATOR","DOCTOR","OPERATIONS","FINANCE").contains(role))throw new ApiException(400,"INVALID_TASK_OWNER","Select a supported task owner role");if("PATIENT".equals(role)){if(subject==null||subject.isBlank())return;Integer patient=jdbc.sql("SELECT count(*) FROM medical_cases c JOIN patient_profiles p ON p.id=c.patient_id WHERE c.id=? AND p.external_subject=?").params(caseId,subject).query(Integer.class).single();if(patient==null||patient==0)throw new ApiException(409,"TASK_OWNER_NOT_ON_CASE","The selected patient account is not linked to this case");return;}Integer assigned=jdbc.sql("SELECT count(*) FROM case_assignments WHERE case_id=? AND assignee_subject=? AND assignee_role=? AND status='ACTIVE'").params(caseId,subject,role).query(Integer.class).single();if(assigned==null||assigned==0)throw new ApiException(409,"TASK_OWNER_NOT_ON_CASE","The selected staff member does not have an active case assignment");}
    private ApiException taskConflict(){return new ApiException(409,"TASK_CONFLICT","The task changed or is not assigned to this account");}
    private void authorizeRead(UUID caseId,ActorContext.Actor actor){if(actor.has(ActorRole.SYSTEM_ADMIN)||actor.has(ActorRole.AUDITOR)||actor.has(ActorRole.COORDINATOR_LEAD))return;if(actor.has(ActorRole.PATIENT)||actor.has(ActorRole.PATIENT_REPRESENTATIVE)){Integer count=jdbc.sql("SELECT count(*) FROM medical_cases c JOIN patient_profiles p ON p.id=c.patient_id WHERE c.id=? AND (p.external_subject=? OR EXISTS(SELECT 1 FROM patient_representatives r WHERE r.patient_id=p.id AND r.representative_subject=? AND r.revoked_at IS NULL AND (r.expires_at IS NULL OR r.expires_at>?)))").params(caseId,actor.subject(),actor.subject(),timestamp(clock.instant())).query(Integer.class).single();if(count!=null&&count>0)return;}else{Integer count=jdbc.sql("SELECT count(*) FROM case_assignments WHERE case_id=? AND assignee_subject=? AND status IN ('PENDING','ACTIVE')").params(caseId,actor.subject()).query(Integer.class).single();if(count!=null&&count>0)return;}throw new ApiException(403,"CASE_ACCESS_DENIED","This account is not authorized to access the case");}
    private void authorizeWrite(UUID caseId,ActorContext.Actor actor){if(actor.has(ActorRole.AUDITOR))throw new ApiException(403,"READ_ONLY_ROLE","Auditors cannot modify records");authorizeRead(caseId,actor);}
    private void requireCoordinatorOwnership(UUID caseId,ActorContext.Actor actor){if(actor.has(ActorRole.SYSTEM_ADMIN))return;if(!actor.has(ActorRole.COORDINATOR)&&!actor.has(ActorRole.COORDINATOR_LEAD))return;Integer owned=jdbc.sql("SELECT count(*) FROM case_assignments WHERE case_id=? AND assignee_subject=? AND assignee_role='COORDINATOR' AND assignment_type='PRIMARY' AND status='ACTIVE'").params(caseId,actor.subject()).query(Integer.class).single();if(owned==null||owned==0)throw new ApiException(409,"CASE_NOT_OWNED","Take ownership of the case before performing this action");}
    private void transitionInternal(UUID caseId,String target,String reason,long expectedVersion,ActorContext.Actor actor){CaseState current=state(caseId);if(current.version()!=expectedVersion)throw new ApiException(409,"CASE_VERSION_CONFLICT","The case was updated by another user");validateTransition(caseId,current.status(),target);int changed=jdbc.sql("UPDATE medical_cases SET status=?,updated_at=?,version=version+1 WHERE id=? AND version=?").params(target,timestamp(clock.instant()),caseId,expectedVersion).update();if(changed!=1)throw new ApiException(409,"CASE_VERSION_CONFLICT","The case was updated by another user");history(caseId,current.status(),target,actor,reason);}
    private void transitionWithoutVersion(UUID caseId,String target,String reason,ActorContext.Actor actor){CaseState current=state(caseId);if(current.status().equals(target))return;validateTransition(caseId,current.status(),target);int changed=jdbc.sql("UPDATE medical_cases SET status=?,updated_at=?,version=version+1 WHERE id=? AND version=?").params(target,timestamp(clock.instant()),caseId,current.version()).update();if(changed!=1)throw new ApiException(409,"CASE_VERSION_CONFLICT","The case was updated by another user");history(caseId,current.status(),target,actor,reason);}
    private void validateTransition(UUID caseId,String current,String target){Set<String>allowed=TRANSITIONS.getOrDefault(current,Set.of());if(!allowed.contains(target))throw new ApiException(409,"INVALID_CASE_TRANSITION","The requested case transition is not allowed");if(!Set.of("CLINICAL_RECOMMENDATION_READY","PROPOSAL_PREPARATION","PROPOSAL_INTERNAL_APPROVAL","PATIENT_DECISION","ACCEPTED","TRAVEL_COORDINATION","ARRIVAL_CONFIRMED","TREATMENT_IN_PROGRESS","DISCHARGED","FOLLOW_UP","CLOSED").contains(target))return;Integer blocking=jdbc.sql("SELECT count(*) FROM case_tasks WHERE case_id=? AND blocking=TRUE AND status IN ('OPEN','IN_PROGRESS')").param(caseId).query(Integer.class).single();if(blocking!=null&&blocking>0)throw new ApiException(409,"BLOCKING_TASKS_OPEN","Complete or cancel blocking tasks before advancing this case");}
    private void requireState(UUID caseId,String expected){requireOneOfStates(caseId,Set.of(expected));}
    private void requireOneOfStates(UUID caseId,Set<String> expected){String actual=state(caseId).status();if(!expected.contains(actual))throw new ApiException(409,"CASE_STATE_CONFLICT","This operation is not available while the case is "+actual);}
    private void requireActiveAssignment(UUID caseId,ActorContext.Actor actor,ActorRole role){Integer count=jdbc.sql("SELECT count(*) FROM case_assignments WHERE case_id=? AND assignee_subject=? AND assignee_role=? AND status='ACTIVE'").params(caseId,actor.subject(),role.name()).query(Integer.class).single();if(count==null||count==0)throw new ApiException(403,"ACTIVE_ASSIGNMENT_REQUIRED","Accept the active assignment before working on this case");}
    private void requireDecidableProposal(UUID versionId){ProposalView view=proposal(versionId);if(!Set.of("RELEASED","VIEWED").contains(view.status()))throw new ApiException(409,"PROPOSAL_NOT_DECIDABLE","This proposal can no longer be viewed or decided");if(view.validUntil()!=null&&!view.validUntil().isAfter(clock.instant()))throw new ApiException(410,"PROPOSAL_EXPIRED","This proposal has expired");}
    private void validateSelectedOptionalItems(UUID versionId,List<UUID> selected){if(selected==null||selected.isEmpty())return;for(UUID itemId:new HashSet<>(selected)){Integer count=jdbc.sql("SELECT count(*) FROM proposal_items WHERE proposal_version_id=? AND id=? AND optional=TRUE").params(versionId,itemId).query(Integer.class).single();if(count==null||count!=1)throw new ApiException(400,"INVALID_OPTIONAL_ITEMS","Selected optional services do not belong to this proposal");}}
    private CaseState state(UUID caseId){return jdbc.sql("SELECT status,version FROM medical_cases WHERE id=?").param(caseId).query((rs,n)->new CaseState(rs.getString("status"),rs.getLong("version"))).optional().orElseThrow(()->new ApiException(404,"CASE_NOT_FOUND","Case was not found"));}
    private void history(UUID caseId,String from,String to,ActorContext.Actor actor,String reason){jdbc.sql("INSERT INTO case_status_history(id,case_id,from_status,to_status,actor_subject,actor_role,reason,created_at) VALUES(?,?,?,?,?,?,?,?)").params(UUID.randomUUID(),caseId,from,to,actor.subject(),actor.primaryRole(),reason,timestamp(clock.instant())).update();audit("CASE_STATUS_CHANGED",actor,caseId,"MedicalCase",caseId.toString(),"TRANSITION","SUCCESS",reason);}
    private UUID practitionerId(String subject){return jdbc.sql("SELECT id FROM practitioner_profiles WHERE external_subject=? AND credentialing_status='VERIFIED'").param(subject).query(UUID.class).optional().orElseThrow(()->new ApiException(403,"DOCTOR_NOT_VERIFIED","The doctor account is not linked to a verified practitioner profile"));}
    private ActorRole parseRole(String role){try{return ActorRole.valueOf(role);}catch(Exception e){throw new ApiException(400,"INVALID_ROLE","The assignment role is invalid");}}
    private ProposalView latestProposal(UUID caseId,ActorContext.Actor actor){String restriction=actor.has(ActorRole.PATIENT)||actor.has(ActorRole.PATIENT_REPRESENTATIVE)?" AND pv.status IN ('RELEASED','VIEWED','ACCEPTED','DECLINED','REVISION_REQUESTED','EXPIRED')":"";return jdbc.sql("SELECT pv.id FROM proposal_versions pv JOIN proposals p ON p.id=pv.proposal_id WHERE p.case_id=?"+restriction+" ORDER BY pv.version_number DESC LIMIT 1").param(caseId).query(UUID.class).optional().map(this::proposal).orElse(null);}
    private void ensureProposalBelongs(UUID caseId,UUID versionId){Integer count=jdbc.sql("SELECT count(*) FROM proposal_versions pv JOIN proposals p ON p.id=pv.proposal_id WHERE pv.id=? AND p.case_id=?").params(versionId,caseId).query(Integer.class).single();if(count==null||count==0)throw new ApiException(404,"PROPOSAL_NOT_FOUND","Proposal version was not found for this case");}
    private ProposalView proposal(UUID versionId){return jdbc.sql("SELECT p.id proposal_id,pv.* FROM proposal_versions pv JOIN proposals p ON p.id=pv.proposal_id WHERE pv.id=?").param(versionId).query((rs,n)->new ProposalView(rs.getObject("proposal_id",UUID.class),rs.getObject("id",UUID.class),rs.getInt("version_number"),rs.getString("status"),rs.getString("language"),rs.getString("currency"),instantNullable(rs,"valid_until"),rs.getString("operational_plan"),rs.getString("included_services"),rs.getString("excluded_services"),rs.getString("payment_terms"),rs.getString("refund_terms"),rs.getString("disclaimers"),proposalItems(versionId),rs.getString("coordinator_notes"),rs.getString("document_type"),rs.getString("scope_change_reason"))).optional().orElseThrow(()->new ApiException(404,"PROPOSAL_NOT_FOUND","Proposal version was not found"));}
    private List<ProposalItemView> proposalItems(UUID versionId){return jdbc.sql("SELECT * FROM proposal_items WHERE proposal_version_id=? ORDER BY sort_order,id").param(versionId).query((rs,n)->new ProposalItemView(rs.getObject("id",UUID.class),rs.getString("category"),rs.getString("description"),rs.getBigDecimal("quantity"),rs.getBigDecimal("unit_price"),rs.getBoolean("optional"))).list();}
    private String renderProposal(ProposalView view){StringBuilder html=new StringBuilder("<article><h1>RehletShifaa Proposal v").append(view.versionNumber()).append("</h1><p>Status: released</p><ul>");for(ProposalItemView item:view.items())html.append("<li>").append(escape(item.description())).append(" — ").append(item.quantity().multiply(item.unitPrice())).append(' ').append(escape(view.currency())).append("</li>");return html.append("</ul><p>Proposal acceptance is not procedure-specific medical consent.</p></article>").toString();}
    private String escape(String value){return value==null?"":value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
    private void audit(String type,ActorContext.Actor actor,UUID caseId,String entity,String entityId,String action,String outcome,String reason){jdbc.sql("INSERT INTO audit_events(id,event_type,actor_subject,actor_role,case_id,entity_type,entity_id,action,outcome,reason,occurred_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)").params(UUID.randomUUID(),type,actor.subject(),actor.primaryRole(),caseId,entity,entityId,action,outcome,reason,timestamp(clock.instant())).update();}
    private static Instant instant(ResultSet rs,String column)throws SQLException{return rs.getObject(column,OffsetDateTime.class).toInstant();}
    private static Instant instantNullable(ResultSet rs,String column)throws SQLException{OffsetDateTime value=rs.getObject(column,OffsetDateTime.class);return value==null?null:value.toInstant();}
    private record CaseState(String status,long version){}
